159.text:
```matlab

function lookahead(P::MDP, U, s, a)

    S, T, R, γ = P.S, P.T, P.R, P.γ

    return R(s,a) + γ*sum(T(s,a,s')*U(s') for s' in S)

end

function lookahead(P::MDP, U::Vector, s, a)

    S, T, R, γ = P.S, P.T, P.R, P.γ

    return R(s,a) + γ*sum(T(s,a,s')*U[i] for (i,s') in enumerate(S))

end

```

