function lookahead(P::POMG, U, s, a)

    S, O, T, O, R, γ = P.S, joint(P.O), P.T, P.O, P.R, P.y

    u' = sum(T(s,a,s')*sum(O(a,s',o)*U(o,s')) for o in O) for s' in S)

    return R(s,a) + γ*u'

end

function evaluate_plan(P::POMG, π, s)

    a = Tuple(πi() for πi in π)

    U(o,s') = evaluate_plan(P, [πi(oi) for (πi, oi) in zip(π,o)], s')

    return isempty(first(π).subplans) ? P.R(s,a) : lookahead(P, U, s, a)

end

function utility(P::POMG, b, π)

    u = [evaluate_plan(P, π, s) for s in P.S]

    return sum(bs * us for (bs, us) in zip(b, u))

end

